function extend(route,tabs,parts,o={}){const cur=subTabs[route]||[];const existing=new Set(cur.map(t=>t[0]));if(o.rename)cur.forEach(t=>{if(o.rename[t[0]])t[1]=o.rename[t[0]]});const add=tabs.filter(t=>!existing.has(t[0]));if(o.prepend)subTabs[route]=[...add.filter(t=>o.prepend.includes(t[0])),...cur,...add.filter(t=>!o.prepend.includes(t[0]))];else subTabs[route]=[...cur,...add];Object.assign(extParts[route]=extParts[route]||{},parts);const orig=views[route];const noSubnav=!cur.length;views[route]=function(){const fn=extParts[route][sub];const html=orig();if(noSubnav){const i=html.indexOf('<div class="page-head">');const j=html.indexOf('</div></div>',i)+12;const headHtml=html.slice(0,j),rest=html.slice(j);return headHtml+`<div class="toolbar">${subnav()}</div>`+(fn?fn():rest)}if(!fn)return html;const i=html.indexOf('<div class="toolbar">');const j=html.indexOf('</div></div>',i)+12;return html.slice(0,j)+fn()}}
