const setBtn=(label,path,value,msg,cls='sm',icon='check')=>`<button class="button ${cls}" data-action="set" data-path="${path}" data-value="${esc(value)}" data-msg="${esc(msg)}">${ic(icon)}<span>${label}</span></button>`;
