const ovScope=()=>ui.ovScope||'Tüm şirket';const ovPeriod=()=>ui.ovPeriod||'Bugün';
function ovFilters(){return `<div class="toolbar"><div class="tabs" aria-label="Dönem">${['Bugün','Bu hafta','Bu ay'].map(p=>`<button class="tab ${ovPeriod()===p?'active':''}" data-action="ui" data-key="ovPeriod" data-value="${p}" aria-pressed="${ovPeriod()===p}">${p}</button>`).join('')}</div><label class="form-field">Kapsam<select data-ui-sel="ovScope">${['Tüm şirket','Jobs Studio','Edit Culture & Events',...state.clients.filter(c=>!c.internal).slice(0,8).map(c=>'Müşteri · '+c.name)].map(s=>option(s,s,ovScope())).join('')}</select></label>${fresh('metric_snapshot',2)}</div>`}
function ovTop5(){const late=myTasks().filter(t=>!t.done&&daysFromToday(t.due)<0);const items=[[`${late.length} geciken görev (en kritik: ${esc(late[0]?.name||'—')})`,'tasks/liste'],[`${state.approvals.filter(a=>a.status==='Bekliyor').length} onay bekliyor; 1’i 86.000 TL (kurucu seviyesi)`,'approvals'],[`${state.invoices.filter(i=>i.status==='Gecikmiş').length} gecikmiş fatura · ${money(state.invoices.filter(i=>i.status==='Gecikmiş').reduce((s,i)=>s+i.amount,0))}`,'finance/alacak'],['Wellana hesap sağlığı 52 → Kasım yenilemesi riskte','crm/pipeline'],[`${state.hrDocs.filter(d=>d.status==='Eksik').length} eksik özlük belgesi · Selin Tekin devri 12.11`,'people/arsiv-eksik']];return panel('Bugün dikkat gerektiren 5 konu',`<ol class="steps" style="padding-left:18px">${items.map(([t,h])=>`<li><a href="#${h}">${t}</a></li>`).join('')}</ol><p class="small muted">AI gündem özeti · izin sınırları içinde; hassas İK/ücret verisi özetlere girmez.</p>`,badge('AI özeti · simüle','ai'))}
function ovPins(){return `<div class="pin-grid">${state.pins.map(p=>`<div class="pin-card"><span>${ic('star')} ${esc(p)}</span><button class="icon-button sm" data-action="pin-remove" data-id="${esc(p)}" aria-label="${esc(p)} sabitlemesini kaldır">${ic('close')}</button></div>`).join('')}<button class="pin-card" data-action="pin-add">${ic('plus')} Kart sabitle</button></div>`}
function ovActivity(){const p=ovPeriod();const rows=state.activity.filter(a=>p==='Bugün'?!a.at.startsWith('Dün'):true);return panel(`Aktivite akışı · ${p}`,`<ul class="meeting-list">${rows.map(a=>`<li><strong class="mono">${esc(a.at)}</strong>${badge(a.kind,'neutral')}<a href="#${a.route}">${esc(a.text)}</a></li>`).join('')}</ul>`,`<span class="small muted">${esc(ovScope())}</span>`)}
function ovQuick(){const q=[['Müşteri oluştur','new-client','crm'],['Proje başlat','new-project','projects'],['Görev aç','new-task','tasks'],['Dosya yükle','goto','upload','transfer/yukle'],['İş talebi al','goto','inbox','inbox'],['Rapor üret','insights-weekly','insights'],['İzin talebi','leave-new','clock'],['Masraf gir','exp-new','wallet']];return panel('Hızlı işlemler',`<div class="link-grid">${q.map(([l,a,i,id])=>`<button class="link-card" data-action="${a}" ${id?`data-id="${id}"`:''}>${ic(i)}<span>${l}</span></button>`).join('')}</div>`)}
function ovAlerts(){const ns=state.notifications;return panel('Uyarılar & bildirim merkezi',`<p class="small muted">Akıllı öncelik: yalnız eylem gerektiren olaylar öne çıkar; aynı olay tekrar bildirim üretmez.</p>${tbl(['ZAMAN','BİLDİRİM','ÖNCELİK',''],ns.map(n=>`<tr class="${n.read?'muted':''}"><td class="mono">${esc(n.time)}</td><td>${esc(n.text)}</td><td>${badge(/onay|hata|gecik|risk/i.test(n.text)?'Eylem':'Bilgi',/onay|hata|gecik|risk/i.test(n.text)?'warn':'neutral')}</td><td>${btn('Git','notif-open','sm','arrow',`data-id="${n.id}"`)}</td></tr>`).join(''),'Bildirimler')}`,btn('Tümünü okundu say','notif-read-all','sm','check'))}
extend('overview',[['ozet','Yönetici özeti'],['kisisel','Kişisel dashboard'],['uyarilar','Uyarılar & bildirim merkezi'],['hizli','Hızlı işlemler']],{kisisel:()=>ovFilters()+ovPins()+`<section class="content-grid">${ovTop5()}${ovActivity()}</section>`,uyarilar:()=>ovFilters()+ovAlerts(),hizli:()=>ovQuick()+ovTop5()});
const _ovView=views.overview;views.overview=function(){const h=_ovView();if(sub!=='ozet')return h;const i=h.indexOf('</div></div>',h.indexOf('<div class="toolbar">'))+12;return h.slice(0,i)+ovFilters()+ovPins()+h.slice(i)+`<section class="content-grid" style="margin-top:20px">${ovTop5()}${ovActivity()}</section>`};

