'pin-add'(){const opts=['Bekleyen onaylar','Geciken görevler','Gecikmiş faturalar','Kapasite',...state.projects.slice(0,4).map(p=>p.name)].filter(x=>!state.pins.includes(x));if(!opts.length){toast('Sabitlenecek kart kalmadı.');return}state.pins.push(opts[0]);done(`“${opts[0]}” sabitlendi.`,`Kart sabitlendi: ${opts[0]}`)},
'task-snooze'(b){const t=state.tasks.find(x=>x.id===b.dataset.id);if(!t)return;const d=new Date(TODAY+'T12:00:00');d.setDate(d.getDate()+1);t.due=d.toISOString().slice(0,10);t.date=date(t.due);done('Görev 1 gün ertelendi.',`Görev ertelendi: ${t.name} → ${t.due}`)},
'task-help'(b){const t=state.tasks.find(x=>x.id===b.dataset.id);if(!t)return;addNotification(`${person(t.owner)} yardım istedi: ${t.name}`,'tasks/liste');requestApproval({name:`Yardım talebi: ${t.name}`,kind:'İçerik',desc:'Geciken iş için yeniden atama / ek kaynak kararı.',task:t.id});done('Yöneticiye bildirim gitti; Onay Merkezi’ne not düştü.',`Yardım istendi: ${t.name}`)},
'lifecycle-move'(b){const c=state.clients.find(x=>x.id===b.dataset.id);if(!c)return;c.lifecycle=b.dataset.to;if(b.dataset.to==='active')c.status='Aktif';if(b.dataset.to==='inactive')c.status='Pasif';if(b.dataset.to==='renewal')c.status='Riskli';emit('client.lifecycle.changed',`client:${c.id}`);done(`${c.name} → ${c.lifecycle}`,`Müşteri yaşam döngüsü: ${c.name} → ${c.lifecycle}`)},
'quote-version'(b){const q=state.quotes.find(x=>x.id===b.dataset.id);if(!q)return;const vs=state.quoteVersions[q.id]=state.quoteVersions[q.id]||[];vs.push({v:'v'+(vs.length+1),at:now(),total:q.items.reduce((s,i)=>s+i[1]*i[2],0),due:q.due||'30 gün',note:'Editörden kaydedildi'});done(`Teklif sürümü ${vs.at(-1).v} kaydedildi.`,`Teklif sürümü: ${q.id} ${vs.at(-1).v}`)},
'quote-item-add'(b){const q=state.quotes.find(x=>x.id===b.dataset.id);if(!q)return;q.items.push(['Yeni kalem',1,10000]);done('Kalem eklendi.',`Teklif kalemi eklendi: ${q.id}`)},
'quote-item-remove'(b){const q=state.quotes.find(x=>x.id===b.dataset.id);if(!q)return;const it=q.items.splice(Number(b.dataset.i),1)[0];done('Kalem silindi.',`Teklif kalemi silindi: ${q.id} · ${it?.[0]}`)},
'quote-send'(b){const q=state.quotes.find(x=>x.id===b.dataset.id);if(!q)return;q.status='Onay bekliyor';requestApproval({name:`Teklif: ${q.name}`,kind:'Bütçe',amount:q.items.reduce((s,i)=>s+i[1]*i[2],0),desc:'Teklif fiyat onayı (müşteriye gönderim öncesi insan onayı).'});done('Teklif onaya gönderildi.',`Teklif onaya gönderildi: ${q.id}`)},
'contract-renew'(b){const c=state.contracts.find(x=>x.id===b.dataset.id);if(!c)return;const l={id:uid('l'),name:`${client(c.client)} · ${c.name} yenileme`,client:client(c.client),value:c.monthly*12,stage:'Teklif',owner:account().person,probability:70,next:'2026-11-15',source:'Yenileme'};state.leads.unshift(l);const cl=brand(c.client);if(cl)cl.lifecycle='renewal';done('Yenileme teklifi lead olarak açıldı (pipeline → renewal).',`Sözleşme yenileme teklifi: ${client(c.client)}`)},
