document.addEventListener('change',e=>{const t=e.target;if(t.dataset.reschedule){const task=state.tasks.find(x=>x.id===t.dataset.reschedule);if(!task)return;task.due=t.value;task.date=date(t.value);done('Görev yeniden planlandı.',`Görev yeniden planlandı: ${task.name} → ${t.value}`)}});

