const curProj=()=>myProjects().find(p=>p.id===ui.proj)||myProjects()[0];
const projSel=()=>`<label class="form-field" style="min-width:260px">Proje<select data-ui-sel="proj">${myProjects().map(p=>option(p.id,p.name,curProj()?.id)).join('')}</select></label>`;
function projHealth(p){const b=state.budgets?.find(x=>x.project===p.id);const spent=b?Math.round(b.actual/b.planned*100):0;const late=state.tasks.filter(t=>t.project===p.id&&!t.done&&daysFromToday(t.due)<0).length;const ms=(p.milestones||[]).filter(m=>!m[2]&&daysFromToday(m[1])<0).length;const scope=(p.scopeChanges||[]).length;return [['Tarih riski',late+ms?`${late} geciken görev · ${ms} geçmiş kilometre taşı`:'Yok',late+ms?'danger':'success'],['Kapsam aşımı',scope?`${scope} kapsam değişikliği`:'Yok',scope?'warn':'success'],['Bütçe tüketimi',`%${spent}`,spent>90?'danger':spent>70?'warn':'success'],['Kaynak darboğazı',state.tasks.filter(t=>t.project===p.id&&t.leaveConflict).length?'İzin çakışması var':'Yok',state.tasks.filter(t=>t.project===p.id&&t.leaveConflict).length?'warn':'success']]}
function gantt(p){const items=[...(p.milestones||[]).map(m=>({n:m[0],from:m[1],to:m[1],done:m[2],ms:true})),...state.tasks.filter(t=>t.project===p.id).map(t=>({n:t.name,from:t.due,to:t.due,done:t.done}))];const all=items.flatMap(i=>[i.from,i.to]).sort();const min=new Date((all[0]||TODAY)+'T12:00:00');min.setDate(min.getDate()-5);const max=new Date((all.at(-1)||TODAY)+'T12:00:00');max.setDate(max.getDate()+5);const span=Math.max(1,(max-min)/86400000);const w=720,lw=220,rh=22;const x=d=>lw+((new Date(d+'T12:00:00')-min)/86400000)/span*(w-lw-10);const h=items.length*rh+30;return `<svg class="gantt" viewBox="0 0 ${w} ${h}" role="img" aria-label="Gantt"><line class="today" x1="${x(TODAY)}" y1="0" x2="${x(TODAY)}" y2="${h}" stroke-width="1"/><text x="${x(TODAY)+3}" y="12" class="lbl">bugün</text>${items.map((it,i)=>{const y=20+i*rh;const x1=it.ms?x(it.from)-4:x(it.from)-26;const late=!it.done&&daysFromToday(it.to)<0;return `<text x="0" y="${y+13}" class="lbl">${esc(it.n.slice(0,34))}</text><rect class="bar ${it.done?'done':late?'late':''}" x="${x1}" y="${y+3}" width="${it.ms?8:30}" height="14" rx="${it.ms?4:3}"><title>${esc(it.n)} · ${it.from}</title></rect>`}).join('')}</svg>`}
extend('projects',[['p360','Proje 360'],['gantt','Gantt / takvim'],['ekip','Kaynak / ekip'],['ayarlar','Proje ayarları']],{
p360:()=>{const p=curProj();if(!p)return '<p class="empty">Proje yok.</p>';const ts=state.tasks.filter(t=>t.project===p.id);const b=state.budgets?.find(x=>x.project===p.id);return `<div class="toolbar">${projSel()}${badge(p.status)}${btn('Brief','brief','sm','files',`data-id="${p.id}"`)}${btn('Kapsam değişikliği','scope-change','sm','flag',`data-id="${p.id}"`)}</div><section class="metrics">${metric('İlerleme',`%${progress(p)}`,`${ts.filter(t=>t.done).length}/${ts.length} görev`,'tasks')}${metric('Bütçe',money(p.budget),b?`gerçekleşen ${money(b.actual)}`:'—','finance')}${metric('Teslim',date(p.due),`${daysFromToday(p.due)} gün`,'clock')}${metric('Kilometre taşı',`${(p.milestones||[]).filter(m=>m[2]).length}/${(p.milestones||[]).length}`,'tamamlanan','flag')}</section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Proje sağlığı</h2></div><div class="panel-body">${kv(projHealth(p).map(([k,v,c])=>[k,badge(v,c)]))}</div></div><div class="panel"><div class="panel-header"><h2>Bilgi merkezi</h2></div><div class="panel-body">${kv([['Müşteri / marka',esc(client(p.client))],['Sözleşme',esc(state.contracts.find(c=>c.client===p.client)?.name||'Tek seferlik iş')],['Kaynak e-posta',`<code class="mono">${esc(state.mails.find(m=>m.client===p.client)?.threadId||'—')}</code>`],['Drive / Media',`<a href="#media/kutuphane">${state.assets.filter(a=>a.project===p.id).length} varlık</a>`],['Review',`<a href="#review/inceleme">${state.reviews.filter(r=>r.project===p.id).length} inceleme</a>`],['Portal görünürlüğü',p.client_visible!==false?badge('Müşteriye açık','success'):badge('Dahili','neutral')]])}</div></div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Görevler</h2>${btn('Görev ekle','new-task','sm','plus',`data-id="${p.id}"`)}</div><div class="panel-body">${ts.map(taskRow).join('')||'<p class="empty">Görev yok.</p>'}</div></section>`},
gantt:()=>{const p=curProj();return `<div class="toolbar">${projSel()}<span class="small muted">Kilometre taşları (elmas) ve görev son tarihleri; kırmızı = geç.</span></div>${panel('Gantt / takvim',gantt(p))}`},
ekip:()=>{const p=curProj();const members=[...new Set(state.tasks.filter(t=>t.project===p.id).map(t=>t.owner))];return `<div class="toolbar">${projSel()}${btn('Freelancer davet et (kısıtlı erişim)','proj-invite','sm','plus',`data-id="${p.id}"`)}</div>${panel('Kaynak / ekip',tbl(['KİŞİ','ROL','PLANLANAN SAAT','GÖREV','KAPASİTE (BU HAFTA)'],members.map(m=>{const t=state.team.find(x=>x.id===m);const al=state.allocations[m]?.[p.id]||0;const cap=state.capacity?.[m]?.[0]||40;return `<tr><td><strong>${esc(person(m))}</strong></td><td>${esc(t?.role||'Freelance / dış')}</td><td><input class="alloc-input" type="number" data-alloc="${m}:${p.id}" value="${al}" style="width:70px" aria-label="Planlanan saat"></td><td>${state.tasks.filter(x=>x.project===p.id&&x.owner===m).length}</td><td>${meter(cap/40*100,cap>40?'over':'')}<small>${cap}/40</small></td></tr>`}).join(''),'Ekip'))}<p class="small muted">Departman ve dış tedarikçi rolleri; freelancer yalnız atandığı projeyi görür.</p>`},
ayarlar:()=>{const p=curProj();const i=state.projects.indexOf(p);return `<div class="toolbar">${projSel()}</div><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Proje ayarları</h2></div><div class="panel-body"><div class="form-grid"><label class="form-field">Durum${sel(`projects.${i}.status`,['Planlama','Aktif','Müşteri bekleniyor','Riskli','Tamamlandı','Arşiv'],p.status,'data-rerender')}</label><label class="form-field">Tür${sel(`projects.${i}.type`,['Kampanya','Sosyal medya','Video prodüksiyon','Etkinlik','Strateji','Web','Marka deneyimi'],p.type)}</label><label class="form-field">Teslim<input type="date" data-bind="projects.${i}.due" value="${p.due}"></label><label class="form-field">Bütçe<input type="number" data-bind="projects.${i}.budget" data-number value="${p.budget}"></label></div><div class="toggle-row"><div><strong>Müşteri portalında görünür</strong><small>Yalnız müşteri görünür teslimler açılır</small></div>${sw(`projects.${i}.client_visible`,p.client_visible!==false,'Müşteriye görünür')}</div></div></div><div class="panel"><div class="panel-header"><h2>Retainer · dönemsel iş üretimi</h2>${badge(p.template==='Sosyal aylık paket'?'Retainer':'Tek seferlik','neutral')}</div><div class="panel-body"><p class="small muted">Aylık sözleşmeli işler için sonraki dönemin proje/iş listesi şablondan otomatik üretilir (kota: sözleşmeden okunur).</p>${btn('Kasım 2026 dönemini üret','proj-period','primary','refresh',`data-id="${p.id}"`)}</div></div></section>`}});

/* ---------- 06 Görevler ---------- */
function taskCal(){const days=[...Array(14)].map((_,i)=>{const d=new Date('2026-10-12T12:00:00');d.setDate(d.getDate()+i);return d.toISOString().slice(0,10)});return `<div class="task-cal">${days.map(d=>`<div class="day ${d===TODAY?'today':''}"><small>${date(d)}</small>${myTasks().filter(t=>t.due===d).map(t=>`<button data-action="task-open" data-id="${t.id}" class="${t.done?'done':''}">${esc(t.name)}</button>`).join('')}</div>`).join('')}</div>`}
extend('tasks',[['takvim','Takvim'],['tablo','Tablo'],['sablonlar','Şablonlar'],['toplu','Toplu işlemler']],{
takvim:()=>panel('Takvim · 12–25 Ekim',taskCal()),
tablo:()=>{const ts=myTasks();return `<div class="toolbar"><label class="form-field">Sırala<select data-ui-sel="tsort">${[['due','Son tarih'],['priority','Öncelik'],['owner','Sorumlu'],['stage','Aşama']].map(([v,l])=>option(v,l,ui.tsort||'due')).join('')}</select></label>${btn('CSV','tasks-csv','sm','download')}</div>${tbl(['GÖREV','PROJE','SORUMLU','AŞAMA','ÖNCELİK','SON TARİH','SLA','SÜRE','ETİKET'],[...ts].sort((a,b)=>String(a[ui.tsort||'due']).localeCompare(String(b[ui.tsort||'due']))).map(t=>`<tr class="${t.done?'muted':''}"><td><button class="task-open" data-action="task-open" data-id="${t.id}"><strong>${esc(t.name)}</strong></button></td><td><small>${esc(project(t.project)?.name)}</small></td><td>${esc(person(t.owner))}</td><td>${badge(t.stage)}</td><td>${badge(t.priority)}</td><td class="${!t.done&&daysFromToday(t.due)<0?'danger-text':''}">${date(t.due)}</td><td>${t.sla}s</td><td>${Math.round((t.logged||0)/60)}s</td><td><small>${(t.labels||[]).join(', ')}</small></td></tr>`).join(''),'Görev tablosu')}`},
sablonlar:()=>panel('Görev şablonları & checklist’ler',`<div class="project-grid">${state.taskTemplates.map(t=>`<article class="panel contract-card"><div class="card-top"><div><h2>${esc(t.name)}</h2><small>${t.items.length} adım</small></div></div><ul class="steps">${t.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul><div class="actions">${btn('Şablondan görev aç','task-from-template','sm primary','plus',`data-id="${t.id}"`)}</div></article>`).join('')}</div>`,btn('Trello geçiş aracı','trello-import','sm','connect')+btn('Şablon ekle','template-add','sm','plus')),
toplu:()=>{const ts=myTasks().filter(t=>!t.done);return `<form id="bulk-form"><div class="toolbar"><label class="form-field">İşlem<select name="op">${[['owner','Sorumlu ata'],['stage','Aşama değiştir'],['label','Etiket ekle'],['due','Son tarih +7 gün'],['done','Tamamla']].map(([v,l])=>option(v,l,'owner')).join('')}</select></label><label class="form-field">Değer<select name="owner">${state.team.map(t=>option(t.id,t.name,'OE')).join('')}</select></label><label class="form-field">Aşama<select name="stage">${['Brief','Kapsam','Plan','Üretim','İç revize','Onay','Teslim','Arşiv'].map(s=>`<option>${s}</option>`).join('')}</select></label><label class="form-field">Etiket<input name="label" value="toplu"></label><button class="button primary" type="submit">Seçililere uygula ${ic('check')}</button></div>${tbl(['<input type="checkbox" data-check-all aria-label="Tümünü seç">','GÖREV','SORUMLU','AŞAMA','SON TARİH'],ts.map(t=>`<tr><td><input type="checkbox" name="ids" value="${t.id}" aria-label="${esc(t.name)}"></td><td>${esc(t.name)}</td><td>${esc(person(t.owner))}</td><td>${badge(t.stage)}</td><td>${date(t.due)}</td></tr>`).join(''),'Toplu işlemler')}</form>`}});
Object.assign(actions,{
'proj-invite'(b){const p=project(b.dataset.id);state.invites.unshift({id:uid('in'),email:'freelancer@example.com',role:'freelancer',sent:now(),expires:'2026-10-21',status:'Bekliyor',scope:p?.name});done('Freelancer daveti gönderildi; erişim yalnız bu projeyle sınırlı.',`Freelancer daveti: ${p?.name}`)},
'proj-period'(b){const p=project(b.dataset.id);if(!p)return;if(state.projects.some(x=>x.periodOf===p.id&&x.period==='2026-11')){toast('Kasım dönemi zaten üretildi (idempotent).');return}const id=uid('p');const c=state.contracts.find(x=>x.client===p.client);state.projects.unshift({id,name:p.name.replace(/Ekim|Sonbahar/,'Kasım'),client:p.client,type:p.type,template:p.template,status:'Planlama',due:'2026-11-30',budget:c?c.monthly:p.budget,summary:'Retainer dönemsel iş üretimi: '+(c?`${c.quota.social} sosyal + ${c.quota.reels} Reels`:'şablondan'),milestones:[['Aylık plan onayı','2026-11-05',false],['Toplu müşteri onayı','2026-11-18',false],['Yayın','2026-11-30',false]],scopeChanges:[],client_visible:p.client_visible,periodOf:p.id,period:'2026-11'});for(let i=0;i<(c?.quota.social||2);i++)state.tasks.unshift({id:uid('t'),name:`${client(p.client)} Kasım sosyal görsel #${i+1}`,project:id,owner:'SK',done:false,date:'20 Kas',due:'2026-11-20',priority:'Normal',stage:'Brief',labels:['retainer','kasım'],type:'Sosyal görsel seti',sla:72,logged:0,comments:[],client_visible:true});emit('project.period.generated',`project:${id}`);done('Kasım dönemi projesi ve görevleri üretildi.',`Retainer dönem üretimi: ${p.name} → Kasım 2026`)},
'tasks-csv'(){csv('gorevler.csv',[['id','name','project','owner','stage','priority','due','sla','logged'],...myTasks().map(t=>[t.id,t.name,project(t.project)?.name,person(t.owner),t.stage,t.priority,t.due,t.sla,t.logged])]);toast('Görev tablosu indiriliyor.')},
'task-from-template'(b){const tp=state.taskTemplates.find(x=>x.id===b.dataset.id);if(!tp)return;state.tasks.unshift({id:uid('t'),name:`${tp.name} (şablondan)`,project:'p6',owner:account().person==='CL'?'SO':account().person,done:false,date:'21 Eki',due:'2026-10-21',priority:'Normal',stage:'Brief',labels:['şablon'],type:tp.name,sla:72,logged:0,comments:[],checklist:tp.items.map(i=>[i,false]),client_visible:false});done('Şablondan görev açıldı (checklist dahil).',`Şablondan görev: ${tp.name}`)},
'template-add'(){state.taskTemplates.push({id:uid('tt'),name:'Yeni şablon',items:['Adım 1','Adım 2']});done('Şablon eklendi.','Görev şablonu eklendi')},
'trello-import'(){openDialog('Trello geçiş aracı',`<form class="dialog-body" id="trello-form"><div class="banner">${ic('connect')}<span>Kademeli içe aktarım: pano → liste → kart → checklist → üye → yorum → ek. Kaynak kimlikleri (card_id, member_id) korunur; iç kimlikler değişmez.</span></div><div class="form-grid"><label class="form-field">Pano<select name="board"><option>Jobs · Müşteri İşleri (412 kart)</option><option>Edit · Etkinlikler (96 kart)</option></select></label><label class="form-field">Liste → aşama eşlemesi<select name="map"><option>To Do → Brief · Doing → Üretim · Review → İç revize · Done → Teslim</option></select></label><label class="form-field">Etiket eşlemesi<select name="labels"><option>Trello etiket → JS etiket (aynı ad)</option></select></label><label class="form-field">Kapsam<select name="scope"><option>Yalnız açık kartlar</option><option>Tüm kartlar (arşiv dahil)</option></select></label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Ön izleme ve içe aktar ${ic('download')}</button></div></form>`)}});
Object.assign(forms,{
'bulk-form'(get,data){const ids=data.getAll('ids').map(String);if(!ids.length){toast('Görev seç.');return}const op=get('op');ids.forEach(id=>{const t=state.tasks.find(x=>x.id===id);if(!t)return;if(op==='owner')t.owner=get('owner');if(op==='stage')t.stage=get('stage');if(op==='label')t.labels=[...new Set([...(t.labels||[]),get('label')])];if(op==='due'){const d=new Date(t.due+'T12:00:00');d.setDate(d.getDate()+7);t.due=d.toISOString().slice(0,10);t.date=date(t.due)}if(op==='done'){t.done=true;t.stage='Teslim'}});done(`${ids.length} görev güncellendi.`,`Toplu işlem (${op}): ${ids.length} görev`)},
'trello-form'(get){const n=5;for(let i=0;i<n;i++)state.tasks.push({id:uid('t'),name:`Trello · ${['Wellana story seti','Dora blog görseli','Anova LinkedIn carousel','Esen vitrin görseli','Noche katalog'][i]}`,project:['p1','p5','p7','p6','p6'][i],owner:['SK','RV','DO','SK','RV'][i],done:false,date:'24 Eki',due:'2026-10-24',priority:'Normal',stage:['Brief','Üretim','İç revize','Üretim','Brief'][i],labels:['trello'],type:'Sosyal görsel seti',sla:72,logged:0,comments:[],trelloId:'trello:card_'+(5100+i),client_visible:false});emit('trello.import.completed','board:jobs');closeDialog();done(`${n} kart içe aktarıldı; kaynak card_id korundu (tekrar çalıştırma idempotent).`,`Trello içe aktarım: ${get('board')} · ${n} kart`)}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.alloc){const [m,p]=t.dataset.alloc.split(':');state.allocations[m]=state.allocations[m]||{};state.allocations[m][p]=Number(t.value);const tot=Object.values(state.allocations[m]).reduce((s,v)=>s+v,0);done(tot>40?`Uyarı: ${person(m)} ${tot} saat (>40) planlandı.`:'Tahsis kaydedildi.',`Kaynak tahsisi: ${person(m)} · ${project(p)?.name} = ${t.value} saat`,false);return}if(t.dataset.checkAll!==undefined){t.closest('table').querySelectorAll('input[name=ids]').forEach(c=>c.checked=t.checked)}});

/* ---------- 07 Resources ---------- */
extend('resources',[['planner','Resource Planner'],['efor','Efor takvimi & timesheet'],['rezervasyon','Ekipman rezervasyonları'],['freelancer','Freelancer rate card’ları']],{
planner:()=>{const ps=state.projects.filter(p=>p.status!=='Tamamlandı').slice(0,6);const leaveWk=id=>state.leaves.filter(l=>l.person===id&&l.status==='Onaylandı'&&l.from<='2026-10-18').reduce((s,l)=>s+(l.days||1)*8,0);return `<p class="small muted">Kişi × proje tahsisi (saat / hafta). Onaylı izin kapasiteden düşer (akış 7.3); 40 saati aşan satır kırmızı. Çakışan görev tarihleri “izin çakışması” etiketi alır; vekil önerisi İzinler’de.</p><div class="panel table-wrap alloc" tabindex="0" role="region" aria-label="Resource Planner"><table><thead><tr><th>KİŞİ</th>${ps.map(p=>`<th><small>${esc(p.name.slice(0,22))}</small></th>`).join('')}<th>TOPLAM</th><th>KAPASİTE</th><th>İZİN</th></tr></thead><tbody>${state.team.map(t=>{const al=state.allocations[t.id]||{};const tot=Object.values(al).reduce((s,v)=>s+v,0);const cap=40-leaveWk(t.id);return `<tr><td><strong>${esc(t.name)}</strong><br><small class="muted">${esc(t.role)}</small></td>${ps.map(p=>`<td class="${tot>cap?'over':''}"><input type="number" min="0" data-alloc="${t.id}:${p.id}" value="${al[p.id]||0}" aria-label="${esc(t.name)} ${esc(p.name)} saat"></td>`).join('')}<td class="${tot>cap?'over':''}"><strong>${tot}</strong></td><td>${cap} s</td><td>${leaveWk(t.id)?badge(`-${leaveWk(t.id)} s`,'warn'):'—'}</td></tr>`}).join('')}</tbody></table></div><p class="small muted" style="margin-top:10px">İzin çakışan görevler: ${state.tasks.filter(t=>t.leaveConflict).map(t=>esc(t.name)).join(', ')||'yok'}.</p>`},
efor:()=>{const days=['12 Eki','13 Eki','14 Eki','15 Eki','16 Eki'];const missing=state.team.filter(t=>!state.timeLogs.some(l=>l.person===t.id)&&t.hours>0);return `${missing.length?`<div class="banner warn-banner">${ic('clock')}<span>Eksik timesheet: ${missing.map(m=>esc(m.name)).join(', ')} bu hafta hiç süre girmedi.</span>${act('Hatırlat','Eksik timesheet hatırlatması gönderildi.','Timesheet hatırlatması: '+missing.length+' kişi','sm','bell')}</div>`:''}${panel('Efor takvimi (gerçekleşen)',tbl(['KİŞİ',...days,'TOPLAM','ONAY'],state.team.map(t=>{const mine=state.timeLogs.filter(l=>l.person===t.id);const tot=mine.reduce((s,l)=>s+l.mins,0);return `<tr><td>${esc(t.name)}</td>${days.map(d=>`<td>${mine.filter(l=>l.at.startsWith(d.slice(0,2)+'.10')).reduce((s,l)=>s+l.mins,0)/60||'—'}</td>`).join('')}<td><strong>${(tot/60).toFixed(1)} s</strong></td><td>${tot?btn('Onayla','effort-approve','sm','check',`data-id="${t.id}"`):badge('Eksik','danger')}</td></tr>`}).join(''),'Efor'))}<p class="small muted">Görev eforu (timesheet) ile personel mesai/puantajı (JS People) ayrı kavramlardır.</p>`},
rezervasyon:()=>panel('Ekipman rezervasyonları',`${tbl(['EKİPMAN','TARİH','KİM','PROJE','DURUM',''],state.equipmentBookings.map(b=>`<tr><td><strong>${esc(b.equipment)}</strong></td><td>${date(b.from)}–${date(b.to)}</td><td>${esc(person(b.by))}</td><td><small>${esc(project(b.project)?.name)}</small></td><td>${badge(b.status,b.status==='Çakışma'?'danger':'success')}</td><td class="actions nowrap">${b.status==='Çakışma'?btn('Alternatif öner','booking-fix','sm','spark',`data-id="${b.id}"`):''}${btn('İptal','booking-cancel','sm','close',`data-id="${b.id}"`)}</td></tr>`).join(''),'Rezervasyonlar')}<p class="small muted">Zimmet ilişkisi JS People → Zimmetler’de; çakışma algılama aynı ekipman + kesişen tarih.</p>`,btn('Rezervasyon','booking-new','sm primary','plus')),
freelancer:()=>panel('Freelancer rate card’ları',`${tbl(['FREELANCER','BİRİM','ÜCRET','MÜSAİTLİK',''],state.rateCards.map((r,i)=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${esc(r.unit)}</td><td><input type="number" data-bind="rateCards.${i}.rate" data-number value="${r.rate}" style="width:100px" aria-label="Ücret"> ${r.currency}</td><td>${esc(r.avail)}</td><td>${btn('Projeye davet','proj-invite','sm','plus','data-id="p3"')}</td></tr>`).join(''),'Rate card')}<p class="small muted">Teklife planlanan kişi/saat maliyeti bu kartlardan gelir; personel ücret maliyeti ayrı ve gizli yetkidir.</p>`)},{rename:{beceri:'Yetkinlik havuzu',kapasite:'Kişi / ekip kapasitesi'}});
Object.assign(actions,{
'effort-approve'(b){done(`${person(b.dataset.id)} efor raporu onaylandı.`,`Efor onayı: ${person(b.dataset.id)}`,false)},
'booking-fix'(b){const bk=state.equipmentBookings.find(x=>x.id===b.dataset.id);if(!bk)return;bk.from='2026-10-23';bk.to='2026-10-24';bk.status='Onaylandı';done('Alternatif tarih atandı; çakışma çözüldü.',`Ekipman rezervasyonu düzeltildi: ${bk.equipment} → ${bk.from}`)},
'booking-cancel'(b){state.equipmentBookings=state.equipmentBookings.filter(x=>x.id!==b.dataset.id);done('Rezervasyon iptal edildi.','Ekipman rezervasyonu iptal')},
'booking-new'(){state.equipmentBookings.push({id:uid('eb'),equipment:'DJI RS4 gimbal',from:'2026-10-27',to:'2026-10-27',by:account().person==='CL'?'HO':account().person,project:'p3',status:'Onaylandı'});done('Rezervasyon oluşturuldu.','Ekipman rezervasyonu: DJI RS4 gimbal 27.10')}});

/* ---------- 08 Finance ---------- */
const PUR_STEPS=['Talep','Teklif karşılaştırma','Onay','Sipariş','Teslim / fatura'];
extend('finance',[['satinalma','Satın almalar'],['alacak','Alacak / borç'],['karlilik','Kârlılık analizi'],['retainer','Retainer takibi'],['nakit','Nakit akışı projeksiyonu'],['defter','Çok şirketli defter']],{
satinalma:()=>panel('Satın alma akışı',`<p class="small muted">${PUR_STEPS.join(' → ')}. Bütçe onayı eşikleri Onay Merkezi politikasından (≤5k otomatik, ≤25k PM, >25k kurucu).</p>${state.purchases.map(p=>{const si=PUR_STEPS.indexOf(p.status);return `<article class="panel contract-card" style="margin-bottom:12px"><div class="card-top"><div><h2>${esc(p.title)}</h2><small>${esc(project(p.project)?.name||'Genel')} · talep: ${esc(person(p.requester))} · ${money(p.amount)} · ${approvalLevel(p.amount)}</small></div>${badge(p.status)}</div><div class="steps flow">${PUR_STEPS.map((s,i)=>`<span class="step ${i<=si?'done':''}">${s}</span>`).join('')}</div>${p.quotes.length?tbl(['TEDARİKÇİ','TEKLİF',''],p.quotes.map(q=>`<tr class="${p.chosen===q[0]?'chosen':''}"><td>${esc(q[0])}</td><td>${money(q[1])}</td><td>${p.status==='Teklif karşılaştırma'?btn('Seç','pur-choose','sm','check',`data-id="${p.id}" data-v="${esc(q[0])}"`):p.chosen===q[0]?badge('Seçildi','success'):''}</td></tr>`).join(''),'Teklifler'):''}<div class="actions">${p.status==='Talep'?btn('Teklif iste (3 tedarikçi)','pur-rfq','sm primary','mail',`data-id="${p.id}"`):p.status==='Teklif karşılaştırma'&&p.chosen?btn('Bütçe onayına gönder','pur-approve','sm primary','approvals',`data-id="${p.id}"`):p.status==='Onay'?badge('Onay Merkezi’nde','warn'):p.status==='Sipariş'?btn('Teslim alındı / fatura eşle','pur-deliver','sm primary','check',`data-id="${p.id}"`):p.order?badge(p.order,'neutral'):''}</div></article>`}).join('')}`,btn('Satın alma talebi','pur-new','sm primary','plus')),
alacak:()=>{const ar=state.invoices.filter(i=>i.status!=='Ödendi');const ap=state.expenses.filter(x=>x.status==='Onaylandı');const bucket=d=>{const n=-daysFromToday(d);return n<=0?'Vadesi gelmemiş':n<=30?'0–30':n<=60?'31–60':'60+'};const ag={};ar.forEach(i=>ag[bucket(i.due)]=(ag[bucket(i.due)]||0)+i.amount);return `<section class="metrics">${metric('Alacak (AR)',money(ar.reduce((s,i)=>s+i.amount,0)),`${ar.length} açık fatura`,'finance')}${metric('Borç (AP)',money(ap.reduce((s,x)=>s+x.amount,0)),`${ap.length} onaylı gider`,'wallet')}${metric('DSO',`${dso()} <small>gün</small>`,'alacak / günlük gelir','clock')}${metric('60+ gün',money(ag['60+']||0),'tahsilat riski','flag')}</section><section class="content-grid">${panel('Alacak yaşlandırma',svgBars(['Vadesi gelmemiş','0–30','31–60','60+'].map(k=>[k,Math.round((ag[k]||0)/1000),k==='60+'?'warn':'']),{unit:'k',label:'Yaşlandırma'}))}${panel('Borçlar (tedarikçi / masraf)',tbl(['KALEM','TEDARİKÇİ','TUTAR','KAYNAK'],ap.map(x=>`<tr><td>${esc(x.desc)}</td><td>${esc(x.supplier)}</td><td>${money(x.amount)}</td><td><small class="mono">${esc(x.source||'finance')}</small></td></tr>`).join(''),'Borçlar'))}</section>`},
karlilik:()=>{const rows=state.projects.map(p=>{const m=projectMargin(p);const rev=p.budget;const direct=rev-Math.round(rev*m.margin/100);const contrib=rev-direct;const opex=Math.round(rev*0.18);return {p,rev,direct,contrib,op:contrib-opex,opex}});return `<div class="banner">${ic('info')}<span><strong>Formüller:</strong> Katkı marjı = Gelir − doğrudan maliyet (efor × saatlik maliyet ${money(RATE)} + freelancer + tedarikçi) ${defBtn('Katkı marjı')} · Faaliyet kârı = Katkı − faaliyet gideri payı (%18, gelir oranıyla) ${defBtn('Faaliyet kârı')} · Net kâr = Faaliyet kârı − finansman − vergi (tahmini) ${defBtn('Net kâr')}. Aynı kavram olarak gösterilmez.</span></div>${tbl(['PROJE','GELİR','DOĞRUDAN MALİYET','KATKI MARJI','FAALİYET GİDERİ PAYI','FAALİYET KÂRI','TEKLİF − GERÇEKLEŞEN'],rows.map(r=>`<tr><td><strong>${esc(r.p.name)}</strong></td><td>${money(r.rev)}</td><td>${money(r.direct)}</td><td>${money(r.contrib)} <small>(%${Math.round(r.contrib/r.rev*100)})</small></td><td>${money(r.opex)}</td><td class="${r.op<0?'danger-text':''}">${money(r.op)}</td><td>${(()=>{const b=state.budgets?.find(x=>x.project===r.p.id);return b?badge(b.actual>b.planned?'Bütçe aşımı':`%${Math.round(b.actual/b.planned*100)} tüketim`,b.actual>b.planned*0.9?'danger':'neutral'):'—'})()}</td></tr>`).join(''),'Kârlılık')}${fresh('JS Finance · bütçe/gider/timesheet',6)}`},
retainer:()=>panel('Retainer takibi',tbl(['MÜŞTERİ','AYLIK BEDEL','DAHİL','KULLANILAN (EKİM)','DEVREDEN HAK','EK İŞ','DURUM'],state.contracts.map(c=>{const used=state.social.filter(s=>s.client===c.client&&s.month==='2026-10').length;const extra=state.approvals.filter(a=>a.kind==='Kapsam dışı'&&project(a.project)?.client===c.client).length;return `<tr><td><strong>${esc(client(c.client))}</strong></td><td>${money(c.monthly)}</td><td>${c.quota.social} sosyal + ${c.quota.reels} Reels + ${c.quota.revize} revize</td><td>${used} içerik · ${c.used.revize} revize</td><td>${Math.max(0,c.quota.social+c.quota.reels-used)} (sonraki aya)</td><td>${extra?badge(`${extra} ek iş teklifi`,'warn'):'—'}</td><td>${badge(used>c.quota.social+c.quota.reels?'Kota aşıldı':'Kapsamda',used>c.quota.social+c.quota.reels?'danger':'success')}</td></tr>`}).join(''),'Retainer')),
nakit:()=>{const labels=['Eki','Kas','Ara','Oca','Şub','Mar'];const inflow=[612,540,480,520,470,510],outflow=[455,470,430,445,440,450],tax=[62,48,118,52,48,112];let bal=380;const cum=inflow.map((v,i)=>bal+=v-outflow[i]-tax[i]);return `${panel('Nakit akışı projeksiyonu (bin TL)',svgLine([{name:'Beklenen tahsilat',data:inflow},{name:'Onaylı ödeme',data:outflow},{name:'Vergi / SGK',data:tax},{name:'Kümülatif nakit',data:cum}],{labels,label:'Nakit akışı'})+legend(['Beklenen tahsilat','Onaylı ödeme','Vergi / SGK','Kümülatif nakit']),fresh('Paraşüt + Finance',12))}<p class="small muted">Beklenen tahsilat = açık faturalar vade olasılığıyla; onaylı ödeme = Onay Merkezi’nden geçen giderler + bordro toplamı (anonim); vergi/SGK uygun kayıtlarla.</p>`},
defter:()=>{const L=ui.ledger||'Konsolide';const l=L==='Jobs Studio'?state.ledgers.jobs:L==='Edit Culture & Events'?state.ledgers.edit:{revenue:state.ledgers.jobs.revenue+state.ledgers.edit.revenue,direct:state.ledgers.jobs.direct+state.ledgers.edit.direct,opex:state.ledgers.jobs.opex+state.ledgers.edit.opex};return `<div class="toolbar"><div class="tabs">${['Jobs Studio','Edit Culture & Events','Konsolide'].map(x=>`<button class="tab ${L===x?'active':''}" data-action="ui" data-key="ledger" data-value="${x}">${x}</button>`).join('')}</div>${L==='Konsolide'?badge('Yalnız yetkili owner','warn'):badge('Ayrı defter','neutral')}</div><section class="metrics">${metric('Gelir (YTD)',money(l.revenue),'2026','finance')}${metric('Doğrudan maliyet',money(l.direct),'efor + dış kaynak','wallet')}${metric('Katkı marjı',money(l.revenue-l.direct),`%${Math.round((l.revenue-l.direct)/l.revenue*100)}`,'insights')}${metric('Faaliyet kârı',money(l.revenue-l.direct-l.opex),'opex sonrası','board')}</section><p class="small muted">Şirketler ayrı defter/raporlama tutar; konsolide görünüm ayrı şirket kayıtlarını korur, yalnız yönetim özetidir. Şirketler arası ID değişimi erişim vermez.</p>`}});
Object.assign(actions,{
'pur-new'(){state.purchases.unshift({id:uid('pr'),title:'Yeni satın alma talebi',project:'',requester:account().person,amount:12000,status:'Talep',quotes:[],chosen:'',order:''});done('Satın alma talebi açıldı.','Satın alma talebi oluşturuldu')},
'pur-rfq'(b){const p=state.purchases.find(x=>x.id===b.dataset.id);if(!p)return;p.quotes=[['Tedarikçi A',p.amount],['Tedarikçi B',Math.round(p.amount*1.08)],['Tedarikçi C',Math.round(p.amount*0.95)]];p.status='Teklif karşılaştırma';done('3 tedarikçiden teklif istendi (simülasyon).',`RFQ gönderildi: ${p.title}`)},
'pur-choose'(b){const p=state.purchases.find(x=>x.id===b.dataset.id);if(!p)return;p.chosen=b.dataset.v;p.amount=p.quotes.find(q=>q[0]===p.chosen)?.[1]||p.amount;done(`${p.chosen} seçildi.`,`Satın alma teklifi seçildi: ${p.title} → ${p.chosen}`)},
'pur-approve'(b){const p=state.purchases.find(x=>x.id===b.dataset.id);if(!p)return;p.status='Onay';const a=requestApproval({name:`Satın alma: ${p.title} (${p.chosen})`,kind:'Bütçe',amount:p.amount,project:p.project,desc:`${approvalLevel(p.amount)} · teklif karşılaştırma tamamlandı.`,purchase:p.id});p.approval=a.id;done('Bütçe onayına gönderildi.',`Satın alma onaya gönderildi: ${p.title} · ${money(p.amount)}`)},
'pur-deliver'(b){const p=state.purchases.find(x=>x.id===b.dataset.id);if(!p)return;p.status='Teslim / fatura';state.expenses.unshift({id:'x-'+p.id,desc:p.title,project:p.project,supplier:p.chosen,amount:p.amount,status:'Onaylandı',category:'Satın alma',date:TODAY,source:'purchase:'+p.id});done('Teslim alındı; gider ve fatura referansı eşlendi.',`Satın alma teslim: ${p.title} · ${p.order}`)}});
const _applyApproval2=applyApproval;applyApproval=function(a){if(a.status==='Onaylandı'&&a.purchase){const p=state.purchases.find(x=>x.id===a.purchase);if(p){p.status='Sipariş';p.order='PO-2026-'+String(30+state.purchases.indexOf(p)+1).padStart(3,'0')}}_applyApproval2(a)};
